mapper.select:
SELECT g.goods_img, g.goods_name, g.goods_desc, ss.remaining_stock, sg.seckill_price, 1 AS count, sg.seckill_price AS pay_amount, o.order_no, o.id, o.order_status, o.create_time FROM seckill_order o LEFT JOIN seckill_goods sg ON o.seckill_goods_id = sg.id AND sg.is_delete = 0 -- 关联库存表 seckill_stock 别名 ss LEFT JOIN seckill_stock ss ON sg.id = ss.seckill_goods_id AND ss.is_delete = 0 LEFT JOIN goods g ON sg.goods_id = g.id WHERE o.is_delete = 0 AND o.user_id = #{userId}
AND o.order_no LIKE CONCAT('%', #{query.orderNo}, '%')
ORDER BY o.id ASC

SELECT COUNT(*) FROM seckill_order o LEFT JOIN seckill_goods sg ON o.seckill_goods_id = sg.id AND sg.is_delete = 0 LEFT JOIN goods g ON sg.goods_id = g.id WHERE o.is_delete = 0
AND o.order_no LIKE CONCAT('%', #{query.orderNo}, '%')
AND o.order_status = #{query.payStatus}
